# ===== Helpers for rendering =====
import html as htmlmod
import base64
import mimetypes
import uuid
import datetime

LANG_CHAPTER = {'en':'Chapter','fr':'Chapitre'}
LANG_TOC = {'en':'Table of contents','fr':'Table des matières'}

def get_chapter_name(lang):
    return LANG_CHAPTER.get(lang, 'Chapter')
def get_toc_name(lang):
    return LANG_TOC.get(lang, 'Table of contents')
def roman_numeral(n):
    vals=[(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    r=""
    for v,s in vals:
        while n>=v:
            r+=s; n-=v
    return r

def clean_text(text, options):
    if not options.get('input.clean', True):
        return text
    if options.get('input.clean.smart_quotes', True):
        # double quotes alternating
        res=[]; open_d=True
        for ch in text:
            if ch=='"':
                res.append('“' if open_d else '”'); open_d=not open_d
            else:
                res.append(ch)
        text=''.join(res)
    if options.get('input.clean.ligature.dashes', False):
        text=text.replace('---','—').replace('--','–')
    if options.get('input.clean.ligature.guillemets', False):
        text=text.replace('<<','«').replace('>>','»')
    return text

def escape_html(s):
    return htmlmod.escape(s, quote=False)

def parse_inline(text, options):
    # code placeholders
    cps=[]
    def cr(m):
        cps.append(m.group(1)); return f"\x00CODE{len(cps)-1}\x00"
    text=re.sub(r'`([^`]+?)`', cr, text)
    text=re.sub(r'~~(.+?)~~', r'<del>\1</del>', text)
    text=re.sub(r'\*\*\*(.+?)\*\*\*', r'<em><b>\1</b></em>', text)
    text=re.sub(r'\*\*(.+?)\*\*', r'<b>\1</b>', text)
    text=re.sub(r'\*([^*]+?)\*', r'<em>\1</em>', text)
    # also _italic_? handle
    text=re.sub(r'(?<!\w)_([^_]+?)_(?!\w)', r'<em>\1</em>', text)
    def lr(m):
        t=m.group(1); u=m.group(2)
        ue=htmlmod.escape(u, quote=True)
        return f'<a href = "{ue}">{t}</a>'
    text=re.sub(r'(?<!!)\[([^\]]+?)\]\(([^)]+?)\)', lr, text)
    def ir(m):
        a=m.group(1); s=m.group(2)
        ae=htmlmod.escape(a, quote=True); se=htmlmod.escape(s, quote=True)
        return f'<img src = "{se}" alt = "{ae}" />'
    text=re.sub(r'!\[([^\]]*?)\]\(([^)]+?)\)', ir, text)
    for idx, code in enumerate(cps):
        esc=htmlmod.escape(code, quote=False)
        text=text.replace(f"\x00CODE{idx}\x00", f"<code>{esc}</code>")
    return text

def parse_blocks(md_text, options):
    lines=md_text.split('\n')
    blocks=[]; footnote_defs={}; i=0; n=len(lines)
    while i<n:
        line=lines[i]; stripped=line.strip()
        if stripped=='':
            i+=1; continue
        if stripped.startswith('```'):
            i+=1; cl=[]
            while i<n and not lines[i].strip().startswith('```'):
                cl.append(lines[i]); i+=1
            if i<n: i+=1
            blocks.append(('code', cl)); continue
        if line.startswith('    ') or line.startswith('\t'):
            cl=[]
            while i<n and (lines[i].startswith('    ') or lines[i].startswith('\t') or lines[i].strip()== ''):
                if lines[i].strip()=='':
                    if i+1<n and (lines[i+1].startswith('    ') or lines[i+1].startswith('\t')):
                        cl.append(''); i+=1; continue
                    else: break
                if lines[i].startswith('    '): cl.append(lines[i][4:])
                elif lines[i].startswith('\t'): cl.append(lines[i][1:])
                else: cl.append(lines[i])
                i+=1
            blocks.append(('code', cl)); continue
        m=re.match(r'^(#{1,6})\s+(.*)$', stripped)
        if m:
            lv=len(m.group(1)); tx=m.group(2).strip()
            tx=re.sub(r'\s+#+\s*$','',tx)
            blocks.append(('heading', lv, tx)); i+=1; continue
        if re.match(r'^\s*([-*_])\s*(\1\s*){2,}$', stripped):
            blocks.append(('hr',)); i+=1; continue
        if stripped.startswith('>'):
            bq=[]
            while i<n and lines[i].strip().startswith('>'):
                l=lines[i].strip()[1:]
                if l.startswith(' '): l=l[1:]
                bq.append(l); i+=1
            blocks.append(('blockquote',' '.join(bq))); continue
        if '|' in line and i+1<n and re.match(r'^\s*\|?[\s\-:|]+\|?\s*$', lines[i+1]) and '-' in lines[i+1]:
            def sr(r):
                r=r.strip()
                if r.startswith('|'): r=r[1:]
                if r.endswith('|'): r=r[:-1]
                return [c.strip() for c in r.split('|')]
            hc=sr(line); i+=2; br=[]
            while i<n and '|' in lines[i] and lines[i].strip()!='':
                br.append(sr(lines[i])); i+=1
            blocks.append(('table', hc, br)); continue
        m_ul=re.match(r'^\s*[-*+]\s+(.*)$', line)
        m_ol=re.match(r'^\s*\d+[.)]\s+(.*)$', line)
        if m_ul or m_ol:
            is_ord=bool(m_ol); items=[]
            while i<n:
                l=lines[i]
                mu=re.match(r'^\s*[-*+]\s+(.*)$', l); mo=re.match(r'^\s*\d+[.)]\s+(.*)$', l)
                if is_ord and mo: items.append(mo.group(1)); i+=1
                elif not is_ord and mu: items.append(mu.group(1)); i+=1
                elif l.strip()=='':
                    if i+1<n:
                        nxt=lines[i+1]; mu2=re.match(r'^\s*[-*+]\s+(.*)$', nxt); mo2=re.match(r'^\s*\d+[.)]\s+(.*)$', nxt)
                        if (is_ord and mo2) or (not is_ord and mu2):
                            i+=1; continue
                    break
                else:
                    if items: items[-1]+=' '+l.strip(); i+=1
                    else: break
            blocks.append(('ul' if not is_ord else 'ol', items)); continue
        m_fn=re.match(r'^\s*\[\^([^\]]+?)\]:\s*(.*)$', line)
        if m_fn:
            footnote_defs[m_fn.group(1)]=m_fn.group(2); i+=1; continue
        # para
        pl=[]
        while i<n and lines[i].strip()!='':
            peek=lines[i].strip()
            if re.match(r'^#{1,6}\s+', peek) or peek.startswith('```') or peek.startswith('>') or re.match(r'^\s*\[\^.+?\]:', lines[i]) or re.match(r'^\s*([-*_])\s*(\1\s*){2,}$', peek) or re.match(r'^\s*[-*+]\s+', lines[i]) or re.match(r'^\s*\d+[.)]\s+', lines[i]) or lines[i].startswith('    ') or lines[i].startswith('\t'):
                break
            if '|' in lines[i] and i+1<n and re.match(r'^\s*\|?[\s\-:|]+\|?\s*$', lines[i+1]) and '-' in lines[i+1]:
                break
            pl.append(lines[i].strip()); i+=1
        if pl:
            blocks.append(('para',' '.join(pl))); continue
        i+=1
    return blocks, footnote_defs

def apply_french_spacing(text, escape=True):
    if escape:
        def rn(m): return f'<span class = "nnbsp">{m.group(1)}&#160;{m.group(2)}</span>'
        text=re.sub(r'(\S+) ([?!;])', rn, text)
        text=re.sub(r'(\S+) :', r'\1\xa0:', text)
    else:
        text=re.sub(r'(\S+) ([?!;])', r'\1\u202f\2', text)
        text=re.sub(r'(\S+) :', r'\1\xa0:', text)
    return text

